url = "example.com"  # Exemple d'URL à pinger

def route(target_url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Exécuter la commande ping
            try:
                result = subprocess.run(['ping', '-c', '1', target_url], 
                                      stdout=subprocess.PIPE, 
                                      stderr=subprocess.PIPE, 
                                      text=True, 
                                      timeout=5)
