import subprocess
import logging
from functools import wraps

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variable to store the URL
url = ""

def ping_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        global url
        # Check if URL is set
        if not url:
            logging.error("URL is not set. Please set the URL before calling the decorated function.")
            return None

        # Run ping command
        try:
            result = subprocess.run(['ping', '-c', '1', url], capture_output=True, text=True, timeout=10)
            if result.returncode == 0:
                logging.info(f"Ping to {url} successful: URL is alive.")
            else:
                logging.warning(f"Ping to {url} failed: URL is not alive.")
        except subprocess.TimeoutExpired:
            logging.error(f"Ping to {url} timed out.")
        except Exception as e:
            logging.error(f"An error occurred while pinging {url}: {e}")

        # Call the original function
        return func(*args, **kwargs)
    return wrapper

# Example usage:
@ping_decorator
def ping():
    logging.info("Ping function executed.")
    return "Ping executed."

# Set the URL
url = "google.com"

# Call the function
ping()

